/** Public deterministic sample-agent frontend; real effects are admitted by existing D1 API. */
const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"A bounded agent task that calls real Cloudflare D1-backed Workform APIs with inspectable evidence.\"><meta name=\"color-scheme\" content=\"light dark\"><title>Daniel Agent — Deterministic Evidence Brief</title>\n<style>\n:root{font:16px/1.55 system-ui,-apple-system,\"Segoe UI\",sans-serif;color-scheme:light dark;--bg:#f7f6f3;--fg:#242825;--muted:#58625c;--panel:#fffefa;--edge:#d4dbd6;--soft:#ebece8;--accent:#785a3c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg)}a{color:inherit}a:hover{text-decoration-thickness:2px}button,input{font:inherit}button{cursor:pointer;min-height:46px;border-radius:9px;border:1px solid var(--edge);background:var(--panel);padding:10px 13px;color:var(--fg);font-weight:650}button:hover:not(:disabled){border-color:var(--accent)}button:disabled{opacity:.62;cursor:wait}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.primary{background:var(--fg);color:var(--panel);border-color:var(--fg)}.skip{position:absolute;top:-80px;background:var(--panel);padding:10px;z-index:10}.skip:focus{top:0}.wrap{max-width:1280px;margin:0 auto;padding:0 22px}.header{background:var(--panel);border-bottom:1px solid var(--edge)}.bar{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;padding:18px 0}.brand{text-decoration:none;font-weight:800;letter-spacing:-.025em}.nav{display:flex;gap:15px;flex-wrap:wrap;font-size:14px}.hero{padding:44px 0 22px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:var(--accent);font-size:12px;font-weight:750}h1{font-size:clamp(33px,5vw,60px);line-height:1.08;letter-spacing:-.052em;margin:9px 0 17px;max-width:920px}.lead{max-width:820px;font-size:18px;color:var(--muted)}.notice{border-left:3px solid var(--accent);background:var(--soft);padding:12px 15px;border-radius:0 7px 7px 0;margin:22px 0}.grid{display:grid;grid-template-columns:minmax(270px,.94fr) minmax(300px,1.12fr) minmax(260px,.94fr);align-items:start;gap:14px;margin:8px 0 50px}.panel{background:var(--panel);border:1px solid var(--edge);border-radius:12px;padding:20px;min-width:0}h2{font-size:20px;letter-spacing:-.03em;margin:0 0 12px}h3{font-size:15px;margin:16px 0 8px}.stack{display:grid;gap:9px}.small{font-size:13px;color:var(--muted)}label{font-size:13px;font-weight:700;display:block;margin-bottom:5px}input{width:100%;border:1px solid var(--edge);border-radius:7px;background:var(--panel);color:var(--fg);padding:10px 11px;font-size:16px}.steps{padding:0;list-style:none;display:grid;gap:10px;counter-reset:step}.steps li{padding:13px;border:1px solid var(--edge);border-radius:8px;background:var(--bg)}.steps strong{display:block;font-size:14px}.steps span{display:block;color:var(--muted);font-size:12px;margin-top:4px}.pill{display:inline-block;padding:3px 9px;border-radius:999px;background:var(--soft);border:1px solid var(--edge);font-size:12px}.trace{font:12px/1.65 ui-monospace,Consolas,monospace;min-height:280px;max-height:600px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--soft);border:1px solid var(--edge);border-radius:8px;padding:14px}.status{min-height:42px;color:var(--muted);font-size:14px;margin:12px 0;overflow-wrap:anywhere}.facts{font:12px/1.7 ui-monospace,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted)}footer{border-top:1px solid var(--edge);padding:25px 0 40px;color:var(--muted);font-size:13px}@media(max-width:1080px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.result{grid-column:1/-1}}@media(max-width:660px){.grid{grid-template-columns:1fr}.result{grid-column:auto}.panel{padding:16px}.hero{padding-top:28px}.wrap{padding:0 16px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media(prefers-color-scheme:dark){:root{--bg:#171a18;--fg:#e8e8df;--muted:#bac5bc;--panel:#242924;--edge:#4d554f;--soft:#323932;--accent:#c8ad90}}\n</style><style id=\"workform-mono-v3\">\n:root{color-scheme:light;--bg:#fff;--fg:#0c0c0c;--panel:#fff;--edge:#dedede;--sub:#f5f5f5;--accent:#111;--muted:#565656}\n@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#0b0b0b;--fg:#f7f7f7;--panel:#171717;--edge:#464646;--sub:#242424;--accent:#f8f8f8;--muted:#c3c3c3}}\nhtml,body{max-width:100%;overflow-x:clip!important}body{background:var(--bg)!important;color:var(--fg)!important;letter-spacing:-.012em}img{filter:grayscale(1)}\n.top,.header{position:relative!important;inset:auto!important;z-index:auto!important;background:var(--panel)!important;backdrop-filter:none!important;border-color:var(--edge)!important}\n.topinner,.bar{min-height:63px!important;padding:10px 0!important}.brand{letter-spacing:-.035em!important;font-size:14px!important}\n.hero{padding:33px 0 22px!important}.hero h1,h1{font-size:clamp(36px,5vw,62px)!important;letter-spacing:-.068em!important;line-height:1.05!important}\n.lede,.lead{font-size:15px!important;line-height:1.69!important}\n.wrap{max-width:1240px!important}.grid,.layout{gap:12px!important;margin-bottom:35px!important}\n.panel,.notice,.steps li,.action,.log,.trace{box-shadow:none!important;border-radius:11px!important;border-color:var(--edge)!important}\n.panel{background:var(--panel)!important;padding:19px!important}\n.notice{background:var(--sub)!important;border-left:3px solid var(--fg)!important}\nbutton,input,textarea,.primary,.group button{border-radius:9px!important;min-height:44px;touch-action:manipulation;box-shadow:none!important}\nbutton{background:var(--panel)!important;color:var(--fg)!important;border:1px solid var(--edge)!important}\nbutton.primary,.primary{background:var(--fg)!important;color:var(--panel)!important;border:1px solid var(--fg)!important}\nbutton:hover:not(:disabled){transform:translateY(-1px)!important}button:active{transform:scale(.987)!important}\ninput,textarea{font-size:16px!important;background:var(--panel)!important;color:var(--fg)!important;border:1px solid var(--edge)!important}\n.log,.trace{background:var(--sub)!important;color:var(--fg)!important}\n.eyebrow,.small,.meta,.facts{color:var(--muted)!important}\nbutton:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid var(--fg)!important;outline-offset:3px!important}\n.mono-link{font-weight:800;text-decoration:none;color:var(--fg)!important;border:1px solid var(--edge);border-radius:9px;padding:9px 12px}\n.mono-link:hover{background:var(--sub)!important}\n@media(max-width:700px){.wrap{padding:0 15px!important}.panel{padding:15px!important}.hero{padding:25px 0 19px!important}.hero h1,h1{font-size:clamp(34px,9vw,48px)!important}.layout,.grid{grid-template-columns:1fr!important}.result{grid-column:auto!important}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important;transform:none!important;scroll-behavior:auto!important}}\n</style><style id=\"agent-dark-cockpit\">\n/* Dark-first deterministic Agent cockpit. One floating navigation trigger; no modal sheets. */\n:root{color-scheme:dark!important;--bg:#090909!important;--fg:#f8f8f8!important;--panel:#161616!important;--edge:#454545!important;--sub:#232323!important;--accent:#fff!important;--muted:#bebebe!important}\nbody{background:#090909!important;color:#f8f8f8!important;padding-bottom:78px}\n.panel,.notice,.steps li,.log,.trace{background:var(--panel)!important;color:var(--fg)!important;border-color:var(--edge)!important}\n.btn.primary,button.primary{background:#f5f5f5!important;color:#0a0a0a!important;border-color:#f5f5f5!important}\nbutton:not(.primary){background:#242424!important;color:#f8f8f8!important;border-color:#535353!important}\ninput,textarea{background:#0f0f0f!important;color:#fff!important;border-color:#555!important}\n.agent-visual-board{border:1px solid #484848;border-radius:16px;background:#151515;padding:20px 22px;margin:5px 0 16px}\n.agent-board-header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:15px}\n.agent-board-header h2{margin:5px 0 0;font-size:clamp(22px,2.8vw,35px);letter-spacing:-.053em;line-height:1.13}\n.agent-board-header>span{display:inline-flex;align-items:center;border:1px solid #666;border-radius:999px;font:800 11px ui-monospace,Consolas,monospace;padding:8px 12px;letter-spacing:.02em;min-height:38px}\n.agent-visual-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;padding:0;margin:0;list-style:none}\n.agent-visual-steps li{display:flex;flex-direction:column;gap:5px;border:1px solid #3d3d3d;border-radius:11px;padding:14px;background:#1d1d1d;min-width:0;transition:border-color .14s,background .14s}\n.agent-visual-steps li>span{font:800 13px ui-monospace,monospace;letter-spacing:.05em;color:#888}\n.agent-visual-steps li strong{font-size:13px;line-height:1.32;color:#eaeaea}\n.agent-visual-steps li small{font-size:11px;line-height:1.55;color:#aaa}\n.agent-visual-steps li[data-state=\"done\"]{background:#292929;border-color:#aaa}\n.agent-visual-steps li[data-state=\"done\"]>span{color:#f9f9f9}\n.agent-visual-steps li[data-state=\"done\"]>span::before{content:\"✓ \"}\n.agent-visual-steps li[data-state=\"running\"]{background:#f5f5f5;border-color:#fff;color:#080808}\n.agent-visual-steps li[data-state=\"running\"] strong,.agent-visual-steps li[data-state=\"running\"] small,.agent-visual-steps li[data-state=\"running\"]>span{color:#161616}\n.agent-proof-caption{font-size:12px;color:#aaa;line-height:1.55;margin:12px 0 0}\n.agent-ask-circle{position:fixed;left:max(15px,env(safe-area-inset-left));bottom:calc(15px + env(safe-area-inset-bottom));z-index:40;width:58px;height:58px;border-radius:50%;border:1px solid #767676;background:#232323;display:grid;place-items:center;box-shadow:0 8px 24px rgba(0,0,0,.42)}\n.agent-ask-circle img{width:44px;height:44px;filter:grayscale(1);border-radius:50%;object-fit:cover}\n.agent-ask-circle:focus-visible{outline:3px solid #fff;outline-offset:3px}\n@media(max-width:950px){.agent-visual-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:560px){.agent-visual-board{padding:15px}.agent-visual-steps li{padding:11px}.agent-visual-steps li strong{font-size:12px}.agent-visual-steps li small{font-size:10px}}\n@media(prefers-reduced-motion:reduce){.agent-visual-steps li,.agent-ask-circle{transition:none!important;transform:none!important}}\n</style></head>\n<body><a class=\"skip\" href=\"#main\">Skip to Agent</a><header class=\"header\"><div class=\"wrap bar\"><a class=\"brand\" href=\"/\">Jemuel Daniel / Engineering</a><nav class=\"nav\" aria-label=\"Site\"><a class=\"mono-link\" href=\"/#ask\">Ask Daniel ↗</a><a href=\"/apps/\">Apps</a><a href=\"/apps/live/\">Workflow + Knowledge</a><a href=\"/apps/workbench/\">API Workbench</a><a href=\"/apps/evidence/\">Engineering proof</a><a href=\"/resume\">Résumé</a></nav></div></header>\n<main id=\"main\" class=\"wrap\"><div class=\"hero\"><div class=\"eyebrow\">Application 03 / Agent systems</div><h1>Watch a bounded agent execute real tools.</h1><p class=\"lead\">Prepare a deterministic evidence brief using a saved Workflow Studio revision and an explicitly selected Knowledge Lab document. Inspect live API operations, server-owned result IDs, passage digests and final document readback.</p><div class=\"notice\"><strong>Verified scope:</strong> An allowlisted browser orchestrator calls the existing Cloudflare D1 guest API. Workflow runs, imported documents and evaluations are actually server-persisted. The orchestration trace is temporary in this browser tab, not a single durable atomic Agent execution receipt. No LLM, arbitrary tools or external actions.</div></div>\n<section class=\"agent-visual-board\" aria-label=\"Observed deterministic agent progression\"><div class=\"agent-board-header\"><div><p class=\"eyebrow\">EXECUTION MONITOR / 04 BOUNDED STEPS</p><h2>Real tool work, visible at each checkpoint.</h2></div><span id=\"agentCurrentLabel\" role=\"status\" aria-live=\"polite\">READY · NOT RUN</span></div><ol class=\"agent-visual-steps\"><li data-agent-step=\"1\" data-state=\"idle\"><span>01</span><strong>Search admitted source</strong><small>Actual ranked document + digest</small></li><li data-agent-step=\"2\" data-state=\"idle\"><span>02</span><strong>Run saved workflow</strong><small>Server run ID + pinned revision</small></li><li data-agent-step=\"3\" data-state=\"idle\"><span>03</span><strong>Commit test artifact</strong><small>Server-owned document receipt</small></li><li data-agent-step=\"4\" data-state=\"idle\"><span>04</span><strong>Verify persisted proof</strong><small>Recomputed SHA-256 match</small></li></ol><p class=\"agent-proof-caption\">Markers turn complete only after the corresponding operation returns from the API. The top-level Agent orchestration is not one atomic persisted server job.</p></section>\n<div class=\"grid\">\n<section class=\"panel\" aria-labelledby=\"control-title\"><h2 id=\"control-title\">01 — Control a sample agent</h2><div class=\"stack\"><button class=\"primary\" id=\"connect\" type=\"button\">Create / resume guest workspace</button><button id=\"seed\" type=\"button\" disabled>Prepare sample workflow + corpus</button><label for=\"query\">Source-document search query</label><input id=\"query\" value=\"atomic evidence\" maxlength=\"160\" spellcheck=\"false\"><button class=\"primary\" id=\"execute\" type=\"button\" disabled>Run new bounded task</button><button id=\"retry\" type=\"button\" disabled>Retry last exact intent</button><button id=\"readback\" type=\"button\" disabled>Verify saved results again</button><button id=\"reset\" type=\"button\" disabled>Delete my test workspace</button></div><p id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">No operation sent. Guest data is ephemeral.</p><h3>Workspace and evidence IDs</h3><p id=\"ids\" class=\"facts\">Not connected.</p></section>\n<section class=\"panel\" aria-labelledby=\"plan-title\"><h2 id=\"plan-title\">02 — Fixed tool plan</h2><ol class=\"steps\"><li><strong>1. Search selected sample corpus</strong><span>GET /apps/api/search · Require cited document and passage digest</span></li><li><strong>2. Execute saved workflow</strong><span>POST /apps/api/runs · Use a stable operation ID for replay</span></li><li><strong>3. Save evidence artifact</strong><span>POST /apps/api/documents · Import server-owned run artifact</span></li><li><strong>4. Verify readback</strong><span>GET /apps/api/runs/:id + /documents/:id · Match source and digest</span></li></ol><h3>Admission boundaries</h3><p class=\"small\">At most four plan steps plus verification reads; no recursive tasks or hidden fan-out. Only fixed URLs are called. Unknown transport outcomes remain unresolved; Retry preserves server operation IDs. Do not enter personal, customer or confidential data.</p><span class=\"pill\">Deterministic · No AI calls</span></section>\n<section class=\"panel result\" aria-labelledby=\"trace-title\"><h2 id=\"trace-title\">03 — Actual trace</h2><p class=\"small\">Operation steps below are observed responses. The server run and document remain readback-capable after reload, while the browser trace is not an authoritative audit ledger.</p><pre id=\"trace\" class=\"trace\" tabindex=\"0\" aria-label=\"Agent execution trace\">Create a guest workspace, prepare the sample, then run the fixed task.</pre><h3>Artifact proof</h3><p id=\"proof\" class=\"facts\">No saved evidence artifact yet.</p><button id=\"copy\" type=\"button\">Copy sanitized trace</button></section>\n</div></main><footer><div class=\"wrap\">Jemuel Daniel · Synthetic sample data and bounded execution only. <a href=\"/apps/live/\">Open full Workflow + Knowledge Studio</a> · <a href=\"/apps/workbench/\">Inspect underlying APIs</a></div></footer>\n<script src=\"/apps/agent/client.js\" defer></script><a class=\"agent-ask-circle\" href=\"/#ask\" aria-label=\"Ask Daniel — open the portfolio assistant\"><img src=\"/assets/portrait.jpg\" width=\"44\" height=\"44\" alt=\"\"></a></body></html>";
const CLIENT="(()=>{\n'use strict';\nconst el=id=>document.getElementById(id),API='/apps/api/',KEY='workform-agent-proof-v1';\nconst controls=['connect','seed','execute','retry','readback','reset'];\nlet s={v:1,workspaceId:null,seedOps:null,workflowId:null,seedDocId:null,plan:null,last:null},busy=false,trace=[];\nconst steps=()=>{el('ids').textContent='Workspace: '+(s.workspaceId||'none')+'\\nWorkflow: '+(s.workflowId||'none')+'\\nSelected source: '+(s.seedDocId||'none')+'\\nRun: '+(s.last?.runId||'none')+'\\nArtifact: '+(s.last?.artifactId||'none')};\nconst status=t=>{el('status').textContent=t};\nconst put=()=>{try{sessionStorage.setItem(KEY,JSON.stringify(s))}catch{}steps()};\nconst clear=()=>{s={v:1,workspaceId:null,seedOps:null,workflowId:null,seedDocId:null,plan:null,last:null};try{sessionStorage.removeItem(KEY)}catch{}steps()};\nconst log=(step,kind,evidence)=>{trace.push({step,kind,evidence});if(trace.length>25)trace=trace.slice(-25);el('trace').textContent=JSON.stringify(trace,null,2);updateAgentVisual(step,kind)};\nfunction updateAgentVisual(step,kind){\n const stages={'search':1,'workflow.run':2,'artifact.save':3,'verify':4},current=stages[step]??0;\n const label=el('agentCurrentLabel');if(!label)return;\n if(step==='error'){label.textContent='NEEDS REVIEW · SEE ACTUAL TRACE';return}\n if(step==='plan'){label.textContent='PLAN ACCEPTED · AWAITING TOOL EVIDENCE'}\n if(current){label.textContent=current===4?'PROVENANCE VERIFIED · 04 / 04':'STEP '+String(current).padStart(2,'0')+' / 04 · '+step.toUpperCase();\n  document.querySelectorAll('[data-agent-step]').forEach(item=>{\n   const n=Number(item.dataset.agentStep);\n   item.dataset.state=n<=current?'done':'idle';\n  });\n }\n}\nconst buttons=()=>{for(const k of controls)el(k).disabled=busy||(k!=='connect'&&!s.workspaceId)||(k==='execute'&&(!s.workflowId||!s.seedDocId))||(k==='retry'&&!s.plan)||(k==='readback'&&!s.last)};\nasync function api(method,path,payload){\n  if(!/^\\/?(session|reset|workflows|runs(?:\\/[a-f0-9-]{36})?|documents(?:\\/[a-f0-9-]{36})?|search\\?q=[^#]*)$/.test(path))throw Error('NON_ALLOWLISTED_OPERATION');\n  const url=API+path.replace(/^\\//,'');\n  const headers={accept:'application/json'};\n  const opts={method,credentials:'same-origin',cache:'no-store',headers};\n  if(method==='POST'){headers['content-type']='application/json';headers['x-workform-csrf']='1';opts.body=JSON.stringify(payload||{});if(opts.body.length>8000)throw Error('INPUT_TOO_LARGE')}\n  const ctl=new AbortController();opts.signal=ctl.signal;\n  const timer=setTimeout(()=>ctl.abort(),12000);\n  try{\n    const r=await fetch(url,opts);const raw=await r.text();\n    if(raw.length>131072)throw Error('RESPONSE_TOO_LARGE');\n    let j;try{j=JSON.parse(raw)}catch{throw Error('NON_JSON_RESPONSE')}\n    if(!r.ok)throw Error('HTTP_'+r.status+'_'+(j.error||'ERROR'));\n    return j;\n  }finally{clearTimeout(timer)}\n}\nfunction guarded(fn){return async()=>{if(busy)return;busy=true;buttons();try{await fn()}catch(e){status(/Abort|network|fetch/i.test(e.message)?'Network outcome unknown. Retry the same intent or inspect persisted data.':e.message);log('error','failed_or_unresolved',String(e.message));}finally{busy=false;buttons()}}}\nasync function connect(){\n  const j=await api('POST','session',{});\n  if(!j.workspaceId)throw Error('SERVER_WORKSPACE_MISSING');\n  if(s.workspaceId&&j.workspaceId!==s.workspaceId)clear();\n  s.workspaceId=j.workspaceId;put();status('Guest session active. Prepare synthetic sample data.');log('session','server', {guestOnly:j.guestOnly,workspaceId:j.workspaceId});buttons();\n}\nasync function ensureCurrent(){\n  try{const r=await api('GET','session');if(!r.workspaceId)throw Error('NO_SESSION');if(s.workspaceId!==r.workspaceId){clear();s.workspaceId=r.workspaceId;put()}status('Existing guest session verified.')}catch{clear();status('Create a guest workspace to run this demo.')}buttons();\n}\nasync function prepare(){\n  s.seedOps ||= {workflow:crypto.randomUUID(),document:crypto.randomUUID()};put();\n  const w=await api('POST','workflows',{name:'Deterministic agent evidence workflow',input:'Verifiable operations require atomic evidence receipts. A repeated operation must return its saved result.',steps:['normalize','lowercase','keywords'],operationId:s.seedOps.workflow});\n  if(!w.workflow?.id)throw Error('SAVE_WORKFLOW_FAILED');s.workflowId=w.workflow.id;put();\n  log('prepare_workflow','server_saved',{workflowId:w.workflow.id,revision:w.workflow.revision,replayed:!!w.replayed});\n  const d=await api('POST','documents',{title:'Synthetic proof-carrying operations',text:'An atomic evidence receipt establishes the result of a bounded operation. This public synthetic passage is intended for deterministic lexical retrieval. The agent must cite the exact document and passage digest.',operationId:s.seedOps.document});\n  if(!d.document?.id)throw Error('SAVE_DOCUMENT_FAILED');s.seedDocId=d.document.id;put();\n  log('prepare_document','server_saved',{documentId:d.document.id,revision:d.document.revision,replayed:!!d.replayed});\n  status('Sample Workflow and Knowledge document saved to D1. You can run the bounded task.');buttons();\n}\nasync function hash(text){\n  const bytes=new TextEncoder().encode(text);const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');\n}\nasync function verify(runId,artifactId){\n  if(!runId||!artifactId)throw Error('READBACK_IDENTITIES_REQUIRED');\n  const rr=await api('GET','runs/'+runId),dr=await api('GET','documents/'+artifactId);\n  if(rr.run?.id!==runId||rr.run.status!=='succeeded'||dr.document?.id!==artifactId||dr.document?.sourceRunId!==runId)throw Error('PERSISTENCE_PROVENANCE_MISMATCH');\n  const expected=rr.run.output?.contentSha256||'',computed=await hash(dr.document.text||'');\n  if(!expected||computed!==expected)throw Error('ARTIFACT_SHA256_MISMATCH');\n  const evidence={runId,artifactId,sourceRunId:dr.document.sourceRunId,contentSha256:computed,documentRevision:dr.document.revision,verified:true};\n  el('proof').textContent=JSON.stringify(evidence,null,2);log('verify','server_readback',evidence);return evidence;\n}\nasync function execute(retry){\n  if(!s.workflowId||!s.seedDocId)throw Error('PREPARE_SAMPLE_FIRST');\n  if(!retry||!s.plan){const query=el('query').value.trim();if(!query||query.length>160)throw Error('INVALID_QUERY');s.plan={query,workflowId:s.workflowId,sourceDocId:s.seedDocId,runOperationId:crypto.randomUUID(),artifactOperationId:crypto.randomUUID(),runId:null,artifactId:null};put()}\n  const p=s.plan;\n  if(p.workflowId!==s.workflowId||p.sourceDocId!==s.seedDocId)throw Error('STALE_PLAN_SOURCE');\n  trace=[];log('plan','admitted_by_ui',{mode:'deterministic',toolCount:4,sourceDocId:p.sourceDocId,query:p.query});\n  const searched=await api('GET','search?q='+encodeURIComponent(p.query));\n  const hit=searched.results?.find(x=>x.documentId===p.sourceDocId);\n  if(!hit?.passage?.sha256)throw Error('SELECTED_SOURCE_HAS_NO_MATCH');\n  log('search','server',{documentId:hit.documentId,revision:hit.revision,passageSha256:hit.passage.sha256,score:hit.score,source:'D1'});\n  const run=await api('POST','runs',{workflowId:p.workflowId,operationId:p.runOperationId});\n  if(run.run?.status!=='succeeded'||!run.run.id)throw Error('WORKFLOW_RUN_NOT_SUCCESSFUL');\n  p.runId=run.run.id;put();\n  log('workflow.run','server',{runId:run.run.id,workflowRevision:run.run.workflowRevision,replayed:!!run.replayed,resultSha256:run.run.output?.contentSha256});\n  const saved=await api('POST','documents',{title:'Agent evidence artifact',sourceRunId:p.runId,operationId:p.artifactOperationId});\n  if(!saved.document?.id)throw Error('ARTIFACT_NOT_SAVED');\n  p.artifactId=saved.document.id;put();\n  log('artifact.save','server',{artifactId:p.artifactId,sourceRunId:p.runId,replayed:!!saved.replayed});\n  await verify(p.runId,p.artifactId);\n  s.last={runId:p.runId,artifactId:p.artifactId,sourceDocId:p.sourceDocId,citationSha256:hit.passage.sha256};put();\n  status('Completed real bounded task. Run, document and SHA-256 provenance verified from D1.');\n}\nasync function readback(){if(!s.last)throw Error('NO_SAVED_RESULT');await verify(s.last.runId,s.last.artifactId);status('Saved run and artifact revalidated after readback.')}\nasync function reset(){\n  if(!confirm('Delete all data in this temporary guest workspace? This cannot be undone.'))return;\n  const r=await api('POST','reset',{confirm:'DELETE MY GUEST WORKSPACE'});\n  if(!r.deleted)throw Error('RESET_NOT_CONFIRMED');clear();trace=[];el('trace').textContent='Workspace revoked and deleted.';el('proof').textContent='No saved artifact.';status('Temporary guest workspace deleted and session revoked.');\n}\nel('connect').addEventListener('click',guarded(connect));\nel('seed').addEventListener('click',guarded(prepare));\nel('execute').addEventListener('click',guarded(()=>execute(false)));\nel('retry').addEventListener('click',guarded(()=>execute(true)));\nel('readback').addEventListener('click',guarded(readback));\nel('reset').addEventListener('click',guarded(reset));\nel('copy').addEventListener('click',guarded(async()=>{try{await navigator.clipboard.writeText(el('trace').textContent);status('Sanitized trace copied.')}catch{status('Clipboard unavailable; select trace text instead.')}}));\ntry{const v=JSON.parse(sessionStorage.getItem(KEY)||'null');if(v?.v===1&&typeof v.workspaceId==='string')s=v}catch{}\nsteps();buttons();ensureCurrent();\n})();";

/* Workform Agent V7 original inspector, fed only by observed existing browser trace. */
const AGENT_V7_CSS="<style id=\"agent-proof-inspector-v7\">\n/* Original, monochrome, evidence-driven UI. Never infer success from progress alone. */\n.agent-inspector{border:1px solid #494949;border-radius:15px;padding:22px;margin:0 0 16px;background:#141414;min-width:0}\n.agent-inspector *{box-sizing:border-box}\n.agent-inspector-head{display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:16px}\n.agent-inspector-head .kicker{margin:0 0 6px;color:#a6a6a6;letter-spacing:.13em;font:750 11px/1.4 ui-monospace,Consolas,monospace}\n.agent-inspector-head h2{color:#fff;font-size:clamp(22px,2.6vw,30px);letter-spacing:-.048em;line-height:1.1;margin:0}\n.agent-inspector-status{border:1px solid #666;background:#212121;border-radius:999px;padding:8px 12px;min-height:34px;max-width:100%;font:700 11px/1.4 ui-monospace,Consolas,monospace;color:#e3e3e3;overflow-wrap:anywhere}\n.agent-inspector-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:15px}\n.agent-inspector-metric{min-width:0;background:#1e1e1e;border:1px solid #3b3b3b;border-radius:10px;padding:13px 12px}\n.agent-inspector-metric span{display:block;color:#aaa;letter-spacing:.06em;font:750 10px/1.35 ui-monospace,Consolas,monospace;text-transform:uppercase}\n.agent-inspector-metric strong{display:block;color:#fff;margin:8px 0 3px;font-size:clamp(18px,2.2vw,27px);line-height:1.2;letter-spacing:-.045em;overflow-wrap:anywhere}\n.agent-inspector-metric small{display:block;color:#aaa;font-size:11px;line-height:1.4}\n.agent-inspector-main{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:12px}\n.agent-inspector-pane{min-width:0;border:1px solid #414141;background:#1b1b1b;border-radius:11px;padding:16px}\n.agent-inspector-pane h3{margin:0 0 6px;font-size:15px;color:#fafafa;letter-spacing:-.02em}\n.agent-inspector-description{font-size:12px;line-height:1.55;margin:0 0 12px;color:#bdbdbd}\n.agent-inspector-ledger{display:grid;gap:7px;margin:0;padding:0;list-style:none;max-height:380px;overflow:auto;overscroll-behavior:contain}\n.agent-inspector-ledger li{min-width:0}\n.agent-inspector-ledger details{border:1px solid #414141;background:#242424;border-radius:9px}\n.agent-inspector-ledger summary{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:9px;align-items:center;padding:12px 10px;cursor:pointer;min-height:48px;list-style:none;color:#f4f4f4}\n.agent-inspector-ledger summary::-webkit-details-marker{display:none}\n.agent-inspector-ledger summary::marker{content:\"\"}\n.agent-inspector-ledger summary:focus-visible{outline:3px solid #fff;outline-offset:2px}\n.agent-inspector-ledger summary b{font:750 10px/1.3 ui-monospace,Consolas,monospace;color:#a8a8a8}\n.agent-inspector-ledger summary strong{font-size:12px;font-weight:720;min-width:0;overflow-wrap:anywhere}\n.agent-inspector-ledger summary em{font:650 10px/1.4 ui-monospace,Consolas,monospace;font-style:normal;color:#c9c9c9}\n.agent-inspector-ledger details[open]{border-color:#8b8b8b}\n.agent-inspector-ledger pre{overflow:auto;max-height:220px;white-space:pre-wrap;overflow-wrap:anywhere;color:#d5d5d5;font:11px/1.65 ui-monospace,Consolas,monospace;border-top:1px solid #454545;margin:0;padding:13px}\n.agent-inspector-empty{padding:14px;border:1px dashed #484848;border-radius:9px;color:#adadad;font-size:12px;line-height:1.55}\n.agent-inspector-proof{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;margin:0 0 13px;border:1px solid #414141;border-radius:9px;background:#111;padding:12px;color:#e5e5e5;font:11px/1.7 ui-monospace,Consolas,monospace;min-height:115px}\n.agent-inspector-copy{width:100%;min-height:46px!important;border:1px solid #eaeaea!important;background:#ededed!important;color:#0b0b0b!important;border-radius:9px!important;font-weight:750!important;text-align:center!important}\n.agent-inspector-copy:disabled{opacity:.43!important;cursor:not-allowed!important}\n.agent-inspector-copy:not(:disabled):hover{background:#ccc!important}\n.agent-inspector-copy:focus-visible{outline:3px solid #fff!important;outline-offset:3px!important}\n.agent-inspector-help{font-size:11px;color:#a7a7a7;margin:10px 0 0;line-height:1.55}\n.agent-inspector-verified .agent-inspector-status{border-color:#c9c9c9;background:#363636}\n@media(max-width:890px){.agent-inspector-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.agent-inspector-main{grid-template-columns:minmax(0,1fr)}}\n@media(max-width:520px){.agent-inspector{padding:12px}.agent-inspector-pane{padding:12px}.agent-inspector-metric{padding:12px 10px}.agent-inspector-ledger summary{grid-template-columns:23px minmax(0,1fr) auto}}\n@media(prefers-reduced-motion:reduce){.agent-inspector *, .agent-inspector *::before,.agent-inspector *::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}\n</style>";
const AGENT_V7_MARKUP="<section class=\"agent-inspector\" id=\"agentInspector\" aria-labelledby=\"agentInspectorTitle\">\n<header class=\"agent-inspector-head\"><div><p class=\"kicker\">EVIDENCE / LIVE OBSERVATIONS</p><h2 id=\"agentInspectorTitle\">Agent execution inspector</h2></div><span class=\"agent-inspector-status\" id=\"agentInspectorState\" role=\"status\" aria-live=\"polite\">NO TOOL RESULTS YET</span></header>\n<div class=\"agent-inspector-metrics\" role=\"group\" aria-label=\"Observed execution facts\">\n<div class=\"agent-inspector-metric\"><span>Observed stages</span><strong id=\"agentInspectorStages\">0 / 4</strong><small>Only confirmed API results</small></div>\n<div class=\"agent-inspector-metric\"><span>Server run</span><strong id=\"agentInspectorRun\">—</strong><small>Actual saved run identifier</small></div>\n<div class=\"agent-inspector-metric\"><span>Saved artifact</span><strong id=\"agentInspectorArtifact\">—</strong><small>Actual server document</small></div>\n<div class=\"agent-inspector-metric\"><span>SHA-256 proof</span><strong id=\"agentInspectorProof\">Pending</strong><small>Recomputed content readback</small></div></div>\n<div class=\"agent-inspector-main\"><section class=\"agent-inspector-pane\" aria-labelledby=\"agentInspectorLedgerTitle\"><h3 id=\"agentInspectorLedgerTitle\">Operation ledger</h3><p class=\"agent-inspector-description\">Expand observed steps for exact server identifiers, revisions, replay markers and digests. Entries are derived from the trace below, not invented progress.</p><ol class=\"agent-inspector-ledger\" id=\"agentInspectorLedger\" aria-label=\"Actual browser-observed tool events\"><li class=\"agent-inspector-empty\">Connect to a guest workspace to observe real tool activity.</li></ol></section>\n<section class=\"agent-inspector-pane\" aria-labelledby=\"agentInspectorReceiptTitle\"><h3 id=\"agentInspectorReceiptTitle\">Verification receipt</h3><p class=\"agent-inspector-description\">Available only after a matching saved run, document and SHA-256 have been read back. This verifies the guest artifact, not the entire browser orchestration atomically.</p><pre class=\"agent-inspector-proof\" id=\"agentInspectorReceipt\" tabindex=\"0\" aria-label=\"Sanitized verified receipt\">No verified receipt yet. Execute a task, then inspect the observed readback.</pre><button id=\"agentInspectorCopy\" class=\"agent-inspector-copy\" type=\"button\" disabled>Copy verified receipt</button><p id=\"agentInspectorCopyStatus\" class=\"agent-inspector-help\" role=\"status\" aria-live=\"polite\">No AI model calls, blockchain operations, or confidential source data.</p></section></div></section>";
const AGENT_V7_CLIENT="(()=>{\n'use strict';\nconst node=id=>document.getElementById(id),root=node('agentInspector'),trace=node('trace'),steps=[...document.querySelectorAll('[data-agent-step]')];\nif(!root||!trace||steps.length!==4)return;\nconst refs={status:node('agentInspectorState'),stages:node('agentInspectorStages'),run:node('agentInspectorRun'),artifact:node('agentInspectorArtifact'),proof:node('agentInspectorProof'),ledger:node('agentInspectorLedger'),receipt:node('agentInspectorReceipt'),copy:node('agentInspectorCopy'),copyStatus:node('agentInspectorCopyStatus'),visual:node('agentCurrentLabel')};\nconst labels={'plan':'Plan accepted','session':'Guest session','prepare_workflow':'Workflow stored','prepare_document':'Corpus stored','search':'D1 lexical search','workflow.run':'Workflow executed','artifact.save':'Artifact persisted','verify':'SHA-256 readback','error':'Review required'};\nconst stageIndex={'search':1,'workflow.run':2,'artifact.save':3,'verify':4};\nconst clip=value=>{const x=typeof value==='string'?value:'';return x.length>13?x.slice(0,8)+'…'+x.slice(-4):x||'—'};\nlet receipt=null;\nfunction observations(){\n try{\n  const v=JSON.parse(trace.textContent);\n  return Array.isArray(v)?v.slice(-25).filter(x=>x&&typeof x==='object'&&!Array.isArray(x)&&typeof x.step==='string'&&typeof x.kind==='string'):[];\n }catch{return []}\n}\nfunction isObserved(event){\n if(event.step==='search')return event.kind==='server'&&typeof event.evidence?.passageSha256==='string'&&event.evidence.passageSha256.length>=32;\n if(event.step==='workflow.run')return event.kind==='server'&&typeof event.evidence?.runId==='string';\n if(event.step==='artifact.save')return event.kind==='server'&&typeof event.evidence?.artifactId==='string';\n if(event.step==='verify')return event.kind==='server_readback'&&event.evidence?.verified===true&&typeof event.evidence?.contentSha256==='string'&&event.evidence.contentSha256.length===64;\n return false;\n}\nfunction issueAfter(events,index){return events.slice(index+1).some(e=>e.step==='error')}\nfunction appendEvidence(event,index){\n const li=document.createElement('li'),details=document.createElement('details'),summary=document.createElement('summary');\n const number=document.createElement('b'),name=document.createElement('strong'),state=document.createElement('em'),content=document.createElement('pre');\n number.textContent=String(index+1).padStart(2,'0');\n name.textContent=Object.hasOwn(labels,event.step)?labels[event.step]:'Observed operation';\n state.textContent=event.step==='error'?'REVIEW':isObserved(event)?'API PROOF':event.kind.replaceAll('_',' ').slice(0,22).toUpperCase();\n let payload={step:event.step,kind:event.kind,evidence:event.evidence??null};\n const raw=JSON.stringify(payload,null,2);\n content.textContent=typeof raw==='string'?raw.slice(0,4200):'No structured evidence';\n summary.append(number,name,state);details.append(summary,content);li.appendChild(details);return li;\n}\nfunction render(){\n const events=observations(),completed=new Set();\n for(const event of events)if(Object.hasOwn(stageIndex,event.step)&&isObserved(event))completed.add(stageIndex[event.step]);\n const run=[...events].reverse().find(e=>e.step==='workflow.run'&&isObserved(e));\n const artifact=[...events].reverse().find(e=>e.step==='artifact.save'&&isObserved(e));\n const verifiedIndex=events.findLastIndex(e=>e.step==='verify'&&isObserved(e));\n const lastVerified=verifiedIndex>=0&&!issueAfter(events,verifiedIndex)?events[verifiedIndex]:null;\n const problem=events.some(e=>e.step==='error')&&(verifiedIndex<0||issueAfter(events,verifiedIndex));\n const count=completed.size;\n refs.stages.textContent=count+' / 4';\n refs.run.textContent=clip(run?.evidence?.runId);\n refs.artifact.textContent=clip(artifact?.evidence?.artifactId);\n refs.proof.textContent=lastVerified?'Verified':problem?'Review':'Pending';\n refs.status.textContent=lastVerified?'VERIFIED · OBSERVED READBACK':problem?'NEEDS REVIEW · CHECK TRACE':events.length?'OBSERVING · '+String(count).padStart(2,'0')+' / 04':'NO TOOL RESULTS YET';\n root.classList.toggle('agent-inspector-verified',Boolean(lastVerified));\n // Correct an older presentation heuristic: never paint missing steps complete when only a later readback is observed.\n for(const element of steps){const n=Number(element.dataset.agentStep);element.dataset.state=completed.has(n)?'done':'idle'}\n if(refs.visual){const label=refs.visual.textContent;\n   if(problem)refs.visual.textContent='NEEDS REVIEW · SEE ACTUAL TRACE';\n   else if(lastVerified)refs.visual.textContent='SHA-256 READBACK VERIFIED · OBSERVED';\n   else if(completed.size&&/PROVENANCE VERIFIED/.test(label))refs.visual.textContent='OBSERVED STAGES '+count+' / 04';\n }\n refs.ledger.replaceChildren();\n if(events.length)events.forEach((event,index)=>refs.ledger.appendChild(appendEvidence(event,index)));\n else{const empty=document.createElement('li');empty.className='agent-inspector-empty';empty.textContent='No observed server operations in this browser tab. Start with Create / resume guest workspace.';refs.ledger.appendChild(empty)}\n receipt=lastVerified?{scope:'Verified guest artifact only — browser Agent plan is not an atomic server transaction',status:'verified',runId:lastVerified.evidence.runId,artifactId:lastVerified.evidence.artifactId,sourceRunId:lastVerified.evidence.sourceRunId,contentSha256:lastVerified.evidence.contentSha256,documentRevision:lastVerified.evidence.documentRevision}:null;\n refs.receipt.textContent=receipt?JSON.stringify(receipt,null,2):problem?'Verification pending after an error. Use the original controls to retry or re-read persisted results.':'No verified receipt yet. Execute a task, then inspect the observed readback.';\n refs.copy.disabled=!receipt;\n}\nrefs.copy.addEventListener('click',async()=>{\n if(!receipt)return;const snapshot=JSON.stringify(receipt,null,2);\n try{await navigator.clipboard.writeText(snapshot);refs.copyStatus.textContent='Sanitized verified guest receipt copied.'}\n catch{refs.copyStatus.textContent='Clipboard unavailable. Select the visible receipt text to copy it manually.';refs.receipt.focus()}\n});\nlet scheduled=false;function queue(){if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;render()})}\nnew MutationObserver(queue).observe(trace,{childList:true,characterData:true,subtree:true});\nrender();\n})();";
function agentV7Html(){return HTML.replace('</head>',AGENT_V7_CSS+'</head>').replace('<div class="grid">',AGENT_V7_MARKUP+'<div class="grid">').replace('<script src="/apps/agent/client.js" defer></script>','<script src="/apps/agent/client.js" defer></script><script src="/apps/agent/inspector.js" defer></script>')}

