const AGENT_V18_HTML="<section id=\"agentV18Root\" class=\"av18\" aria-labelledby=\"av18Title\">\n  <header class=\"av18-intro\">\n    <div><p class=\"av18-eyebrow\">APPLICATION 03 / BOUNDED AUTONOMOUS SYSTEMS <span>V18</span></p>\n      <h2 id=\"av18Title\">An agent you can inspect.</h2>\n      <p>Run four admitted tools, follow the actual API evidence, and independently re-read the persisted result. No simulated success badges.</p></div>\n    <span class=\"av18-top-proof\"><i aria-hidden=\"true\"></i> FIXED PLAN · ACTUAL D1 API · NO MODEL CALL</span>\n  </header>\n  <div class=\"av18-shell\">\n    <aside class=\"av18-operator\" aria-labelledby=\"av18OperatorTitle\">\n      <div class=\"av18-panel-kicker\">01 / CONTROL</div>\n      <h3 id=\"av18OperatorTitle\">Mission control</h3>\n      <p>Four bounded operations. No arbitrary tool invocation.</p>\n      <label for=\"av18Question\">Knowledge search</label>\n      <input id=\"av18Question\" type=\"text\" maxlength=\"160\" spellcheck=\"false\" value=\"atomic evidence\" placeholder=\"A query for your sample corpus\">\n      <div class=\"av18-operation-buttons\">\n        <button type=\"button\" id=\"av18Connect\"><span class=\"av18-index\">01</span> Connect guest <span aria-hidden=\"true\">↗</span></button>\n        <button type=\"button\" id=\"av18Seed\" disabled><span class=\"av18-index\">02</span> Prepare sample <span aria-hidden=\"true\">↗</span></button>\n        <button type=\"button\" id=\"av18Execute\" class=\"av18-main-action\" disabled><span class=\"av18-index\">03</span> Execute agent <span aria-hidden=\"true\">↗</span></button>\n      </div>\n      <div class=\"av18-secondary-actions\">\n        <button type=\"button\" id=\"av18Retry\" disabled>Retry same intent</button>\n        <button type=\"button\" id=\"av18Readback\" disabled>Verify readback</button>\n      </div>\n      <div class=\"av18-session\">\n        <span class=\"av18-mono\">SESSION SCOPE</span><strong id=\"av18Session\">NOT CONNECTED</strong>\n        <span>Temporary guest-owned API records. No account or private files.</span>\n      </div>\n      <button type=\"button\" id=\"av18Reset\" class=\"av18-delete\" disabled>Delete guest workspace</button>\n      <p class=\"av18-operator-status\" id=\"av18OperatorStatus\" role=\"status\" aria-live=\"polite\">Create a workspace to enable bounded tasks.</p>\n    </aside>\n    <section class=\"av18-workspace\" aria-labelledby=\"av18TimelineTitle\">\n      <header class=\"av18-workspace-head\">\n        <div><p class=\"av18-panel-kicker\">02 / TOOL TIMELINE</p><h3 id=\"av18TimelineTitle\">Execution graph</h3></div>\n        <span id=\"av18LiveState\" class=\"av18-live-state\" role=\"status\" aria-live=\"polite\" data-state=\"idle\">NOT EXECUTED</span>\n      </header>\n      <div class=\"av18-graph\" aria-label=\"Four-step evidence carrying operation graph\">\n        <div class=\"av18-graph-node\" data-av18-stage=\"search\" data-state=\"idle\"><span class=\"av18-node-num\">01</span><strong>Retrieve</strong><small>Search D1</small></div>\n        <div class=\"av18-graph-node\" data-av18-stage=\"run\" data-state=\"idle\"><span class=\"av18-node-num\">02</span><strong>Execute</strong><small>Saved run</small></div>\n        <div class=\"av18-graph-node\" data-av18-stage=\"artifact\" data-state=\"idle\"><span class=\"av18-node-num\">03</span><strong>Persist</strong><small>Artifact</small></div>\n        <div class=\"av18-graph-node\" data-av18-stage=\"verify\" data-state=\"idle\"><span class=\"av18-node-num\">04</span><strong>Validate</strong><small>SHA-256</small></div>\n      </div>\n      <div class=\"av18-progress\" aria-label=\"Observed completed operation count\"><span id=\"av18ProgressFill\" style=\"width:0\"></span></div>\n      <div class=\"av18-graph-caption\"><span>Real API response gates only</span><strong id=\"av18ProgressLabel\">0 / 4 OBSERVED</strong></div>\n      <div class=\"av18-telemetry\">\n        <div class=\"av18-telemetry-heading\"><h4>Observed tool events</h4><span id=\"av18EventCount\">00</span></div>\n        <ol id=\"av18EventList\" class=\"av18-events\" aria-label=\"Actual observed API operations\">\n          <li class=\"av18-empty\">No server operation is recorded in this tab. Connect and prepare to begin.</li>\n        </ol>\n        <div class=\"av18-note\">The top-level agent plan is browser orchestration. A workflow run and evidence document are individually server-persisted; this timeline is <strong>not</strong> an atomic server job receipt.</div>\n      </div>\n    </section>\n    <aside class=\"av18-evidence\" aria-labelledby=\"av18EvidenceTitle\">\n      <div class=\"av18-evidence-head\"><p class=\"av18-panel-kicker\">03 / READBACK PROOF</p><h3 id=\"av18EvidenceTitle\">Evidence ledger</h3></div>\n      <div class=\"av18-evidence-badge\" id=\"av18Verdict\" data-state=\"pending\"><span class=\"av18-verdict-dot\"></span><strong id=\"av18VerdictText\">Awaiting observed proof</strong></div>\n      <dl class=\"av18-metrics\">\n        <div><dt>Workflow execution</dt><dd id=\"av18RunId\">—</dd></div>\n        <div><dt>Saved document</dt><dd id=\"av18ArtifactId\">—</dd></div>\n        <div><dt>SHA-256 comparison</dt><dd id=\"av18Hash\">—</dd></div>\n        <div><dt>Source passage</dt><dd id=\"av18Source\">—</dd></div>\n      </dl>\n      <button type=\"button\" id=\"av18Export\" disabled class=\"av18-export\">Download verified receipt <span aria-hidden=\"true\">↓</span></button>\n      <p id=\"av18ExportStatus\" class=\"av18-export-status\" role=\"status\" aria-live=\"polite\">A downloadable record is enabled only after real server readback.</p>\n      <a href=\"/apps/workbench/\" class=\"av18-ref\">Inspect the underlying API workbench <span aria-hidden=\"true\">↗</span></a>\n    </aside>\n  </div>\n</section>";
const AGENT_V18_CSS="<style id=\"agent-v18-style\">/* Original V18 Agent proof cockpit. No overlay, no third-party CSS or fake successes. */\n.av18{--a-bg:#0a0e15;--a-panel:#101827;--a-surface:#172336;--a-border:#394d69;--a-fg:#f5f8ff;--a-muted:#b8c7db;--a-ice:#d8e8fc;min-width:0;margin:14px 0 20px;color:var(--a-fg);font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif}\n.av18 *{box-sizing:border-box}\n.av18 button{cursor:pointer;font:inherit;touch-action:manipulation}\n.av18 button:disabled{opacity:.48;cursor:not-allowed}\n.av18 :is(button,input,a):focus-visible,#agentV18Advanced>summary:focus-visible{outline:3px solid #f3f8ff!important;outline-offset:3px!important}\n.av18-intro{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:2px 3px 15px}\n.av18-eyebrow,.av18-panel-kicker{margin:0 0 9px!important;color:#b8d4f8!important;font:750 10px/1.5 ui-monospace,Consolas,monospace;letter-spacing:.105em}\n.av18-eyebrow span{color:#849ab7;margin-left:8px}\n.av18-intro h2{font-size:clamp(31px,4vw,47px);line-height:1.07;letter-spacing:-.065em;color:#fff;font-weight:760;margin:0 0 8px}\n.av18-intro p:not(.av18-eyebrow){margin:0;color:#b8c6d8;font-size:13px;max-width:720px;line-height:1.65}\n.av18-top-proof{display:flex;align-items:center;gap:8px;border:1px solid #425976;border-radius:9px;background:#121e2c;color:#dce9f9;padding:9px 11px;font:760 9px/1.4 ui-monospace,Consolas,monospace;letter-spacing:.045em;max-width:100%}\n.av18-top-proof i{height:8px;width:8px;border-radius:50%;background:#e0ebfa;border:1px solid #fff;flex:none}\n.av18-shell{display:grid;grid-template-columns:235px minmax(0,1fr) 250px;gap:11px;min-width:0;align-items:stretch}\n.av18-operator,.av18-workspace,.av18-evidence{min-width:0;border:1px solid var(--a-border);border-radius:14px;background:#101827}\n.av18-operator{padding:18px 15px}\n.av18-operator h3,.av18-workspace h3,.av18-evidence h3{font-size:19px;letter-spacing:-.045em;line-height:1.18;color:#fff;margin:0 0 5px}\n.av18-operator>p:not(.av18-panel-kicker):not(.av18-operator-status){font-size:11px;line-height:1.6;color:#b9c8dc;margin:0 0 20px}\n.av18-operator>label{display:block;color:#e4eefb;font-size:11px;font-weight:750;margin-bottom:8px}\n#av18Question{width:100%;min-height:45px;max-width:100%;min-width:0;padding:10px 11px;border:1px solid #627b9d;background:#0c131e;border-radius:9px!important;font-size:13px;color:#fff;box-shadow:none!important}\n.av18-operation-buttons{display:grid;gap:7px;margin:14px 0 10px}\n.av18-operation-buttons button{min-height:48px;display:flex;gap:9px;align-items:center;text-align:left;padding:10px 11px;border:1px solid #4b6382;border-radius:10px;background:#223147;color:#ecf3ff;font-size:12px;font-weight:760}\n.av18-operation-buttons button>span:last-child{margin-left:auto}\n.av18-operation-buttons .av18-main-action{border-color:#ecf3ff!important;background:#e7effa!important;color:#0e1929!important}\n.av18-index{font:760 10px ui-monospace,Consolas,monospace;color:#99b0d0}\n.av18-main-action .av18-index{color:#334c6d}\n.av18-secondary-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:8px 0 22px}\n.av18-secondary-actions button{min-height:45px;padding:9px 7px;border-radius:8px;background:#172337;border:1px solid #465e7c;color:#dce9f8;font-size:10px;font-weight:740;line-height:1.3}\n.av18-session{display:grid;gap:5px;border-top:1px solid #344760;border-bottom:1px solid #344760;padding:13px 1px;margin-bottom:13px}\n.av18-mono{font:780 9px ui-monospace,Consolas,monospace;letter-spacing:.08em;color:#acbfd9}\n.av18-session strong{font-size:12px;color:#fff;letter-spacing:-.015em;overflow-wrap:anywhere}\n.av18-session>span:last-child{font-size:10px;color:#a5b7cc;line-height:1.6}\n.av18-delete{width:100%;min-height:44px;background:#111b2a;border:1px solid #70809a;color:#dae6f8;border-radius:9px;padding:9px;font-size:11px;font-weight:760}\n.av18-delete[data-armed=\"true\"]{color:#0e1927;background:#f5f7fa;border-color:#f5f7fa}\n.av18-operator-status{font-size:11px!important;color:#aebfd6;line-height:1.6;margin:12px 0 0!important;overflow-wrap:anywhere}\n.av18-workspace{padding:18px;display:flex;flex-direction:column;gap:13px}\n.av18-workspace-head{display:flex;justify-content:space-between;gap:8px;align-items:start;flex-wrap:wrap}\n.av18-workspace-head h3{font-size:22px;margin:0}\n.av18-live-state{font:760 10px ui-monospace,Consolas,monospace;border:1px solid #435875;color:#adbed3;background:#172333;border-radius:9px;padding:8px 10px;letter-spacing:.03em}\n.av18-live-state[data-state=\"verified\"]{color:#0e1a29;border-color:#fff;background:#dceafc}\n.av18-live-state[data-state=\"review\"]{color:#fff;border-color:#c2d3e7;background:#3a4255}\n.av18-graph{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;min-width:0;padding:16px 10px;border-radius:12px;background:radial-gradient(ellipse at 50% 12%,rgba(206,225,255,.11),transparent 67%),repeating-linear-gradient(90deg,transparent 0px,transparent 25px,rgba(215,234,255,.025) 26px),#0b131e;border:1px solid #354c69}\n.av18-graph-node{position:relative;display:grid;align-content:start;gap:5px;min-width:0;min-height:117px;padding:11px 7px 9px;border:1px solid #415672;border-radius:10px;background:#131e2d}\n.av18-graph-node:not(:last-child)::after{content:\"\";position:absolute;top:49px;left:100%;height:1px;width:9px;background:#7087a4;z-index:1}\n.av18-node-num{height:25px;width:25px;border:1px solid #5b7291;border-radius:7px;display:grid;place-items:center;color:#dbe9fa;font:760 11px ui-monospace,monospace}\n.av18-graph-node strong{font-size:12px;color:#edf6ff;line-height:1.3;letter-spacing:-.025em}\n.av18-graph-node small{font-size:10px;line-height:1.4;color:#9bafc9}\n.av18-graph-node[data-state=\"observed\"]{border-color:#d3e6fc;background:#273b54}\n.av18-graph-node[data-state=\"observed\"] .av18-node-num{color:#0c1725;background:#e4f0ff;border-color:#e4f0ff}\n.av18-graph-node[data-state=\"observed\"] small{color:#dae9fb}\n.av18-graph-node[data-state=\"active\"]{border-color:#b5cee9;background:#1d3047}\n.av18-progress{height:4px;border-radius:100px;overflow:hidden;background:#344861}\n.av18-progress>span{display:block;height:100%;background:#d4e8ff;transition:width 260ms cubic-bezier(.2,.75,.22,1)}\n.av18-graph-caption{display:flex;justify-content:space-between;align-items:center;gap:10px;color:#a8bbd3;font-size:10px}\n.av18-graph-caption strong{font:790 10px ui-monospace,Consolas,monospace;color:#f3f8ff;white-space:nowrap}\n.av18-telemetry{min-width:0;margin-top:6px;flex:1}\n.av18-telemetry-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:9px}\n.av18-telemetry h4{font-size:12px;color:#eff6ff;margin:0;letter-spacing:-.01em}\n#av18EventCount{border:1px solid #526986;background:#18283b;color:#fff;border-radius:8px;padding:4px 7px;font:750 10px ui-monospace,monospace}\n.av18-events{display:grid;gap:6px;list-style:none;padding:0;margin:0;max-height:242px;overflow-y:auto}\n.av18-events li{display:grid;grid-template-columns:31px minmax(0,1fr) auto;align-items:center;gap:8px;border:1px solid #354961;border-radius:9px;background:#172439;padding:9px;min-width:0}\n.av18-events li .av18-event-index{font:700 10px ui-monospace,monospace;color:#96aecc}\n.av18-events li strong{font-size:11px;font-weight:780;line-height:1.3;color:#e7f1ff;overflow-wrap:anywhere}\n.av18-events li em{font:750 9px ui-monospace,monospace;color:#b7cde9;font-style:normal;white-space:nowrap}\n.av18-events li.av18-empty{display:block;color:#a5b6ce;font-size:11px;line-height:1.6;overflow-wrap:normal;word-break:normal}\n.av18-note{border-left:2px solid #94aac6;padding:9px 0 9px 11px;margin-top:14px;font-size:10px;line-height:1.65;color:#a5b9d4}\n.av18-note strong{color:#eef5fe;font-weight:760}\n.av18-evidence{padding:18px 14px}\n.av18-evidence-head{margin-bottom:13px}\n.av18-evidence-badge{display:flex;align-items:center;gap:10px;min-height:57px;padding:12px 10px;border:1px solid #47607d;border-radius:10px;background:#18283a;margin-bottom:14px}\n.av18-evidence-badge strong{font-size:12px;line-height:1.38;color:#dce8f9}\n.av18-evidence-badge[data-state=\"verified\"]{background:#e2eefc;border-color:#fff}\n.av18-evidence-badge[data-state=\"verified\"] strong{color:#0d1928}\n.av18-evidence-badge[data-state=\"review\"]{border-color:#c4d5eb}\n.av18-verdict-dot{height:9px;width:9px;flex:none;border:1px solid #9cb4d1;border-radius:50%;background:#5d789a}\n.av18-evidence-badge[data-state=\"verified\"] .av18-verdict-dot{background:#10243e;border-color:#10243e}\n.av18-metrics{display:grid;gap:7px;margin:0 0 15px}\n.av18-metrics>div{display:grid;gap:6px;padding:10px 11px;border:1px solid #3b506b;border-radius:9px;background:#18283b;min-width:0}\n.av18-metrics dt{font-size:10px;color:#b4c6dd}\n.av18-metrics dd{margin:0;font:760 11px/1.45 ui-monospace,Consolas,monospace;color:#f3f8ff;overflow-wrap:anywhere}\n.av18-export{min-height:45px;width:100%;display:flex;align-items:center;justify-content:space-between;gap:7px;padding:10px!important;background:#dceafc!important;border:1px solid #e9f3ff!important;color:#112035!important;border-radius:9px!important;font-size:11px!important;font-weight:750!important;line-height:1.3}\n.av18-export-status{font-size:10px;line-height:1.6;color:#b3c6df;margin:10px 0 17px}\n.av18-ref{display:inline-flex;align-items:center;gap:7px;min-height:39px;color:#d3e6ff;font-size:11px;font-weight:750;line-height:1.5;text-decoration:underline;text-underline-offset:3px;overflow-wrap:anywhere}\n#agentV18Advanced{border:1px solid #415573;border-radius:12px;background:#101827;margin:15px 0 36px;min-width:0}\n#agentV18Advanced>summary{display:flex;align-items:center;justify-content:space-between;gap:11px;padding:13px 18px;min-height:52px;color:#edf6ff;font-size:13px;font-weight:760;letter-spacing:-.015em;cursor:pointer}\n#agentV18Advanced>summary small{font:680 10px ui-monospace,monospace;color:#abc1da}\n#agentV18Advanced[open]>summary{border-bottom:1px solid #344863;margin-bottom:13px}\n#agentV18Advanced .agent-visual-board{margin:14px 18px}\n#agentV18Advanced .agent-inspector{margin:14px 18px}\n#agentV18Advanced>.grid{margin:14px 18px}\n.agent-v18-body .hero{padding:22px 0 13px!important;min-height:0!important}\n.agent-v18-body .hero h1{font-size:clamp(26px,3.6vw,42px)!important;margin:8px 0 9px!important}\n.agent-v18-body .hero .lead{font-size:12px!important;line-height:1.6!important;max-width:820px!important}\n.agent-v18-body .hero .notice{font-size:11px!important;padding:10px 13px!important;margin:12px 0 5px!important}\n@media(prefers-reduced-motion:no-preference){\n .av18-operation-buttons button:not(:disabled),.av18-secondary-actions button:not(:disabled),.av18-export:not(:disabled),.av18-delete:not(:disabled){transition:background-color 200ms,border-color 200ms,transform 180ms cubic-bezier(.2,.8,.2,1)}\n .av18-operation-buttons button:not(:disabled):active,.av18-secondary-actions button:not(:disabled):active,.av18-export:not(:disabled):active{transform:scale(.975)}\n .av18-graph-node[data-state=\"observed\"] .av18-node-num{animation:av18-acknowledge .35s cubic-bezier(.2,.78,.22,1)}\n}\n@keyframes av18-acknowledge{from{transform:scale(.8);opacity:.45}to{transform:scale(1);opacity:1}}\n@media(max-width:1100px){.av18-shell{grid-template-columns:240px minmax(0,1fr)}.av18-evidence{grid-column:1/-1}.av18-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:700px){.av18-shell{grid-template-columns:minmax(0,1fr)}.av18-intro{align-items:start}.av18-workspace,.av18-operator,.av18-evidence{padding:14px}.av18-evidence{grid-column:auto}.av18-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.av18-graph{gap:5px;padding:10px 6px}.av18-graph-node{min-height:112px;padding:8px 5px}.av18-graph-node strong{font-size:10px}.av18-graph-node small{font-size:9px}.av18-graph-node:not(:last-child)::after{width:5px;top:45px}.av18-intro h2{font-size:33px}}\n@media(max-width:350px){.av18-graph{grid-template-columns:repeat(2,minmax(0,1fr))}.av18-graph-node:not(:last-child)::after{display:none}.av18-graph-node{min-height:90px}.av18-metrics{grid-template-columns:1fr}.av18-intro h2{font-size:29px}}\n@media(prefers-reduced-motion:reduce){.av18 *, .av18 *::before,.av18 *::after{animation:none!important;transition:none!important;transform:none!important;scroll-behavior:auto!important}}\n</style>";
const AGENT_V18_CLIENT="/* Original V18 Agent cockpit: renders ONLY observed guest-API evidence. No extra network. */\n(()=>{\n'use strict';\nconst root=document.getElementById('agentV18Root');\nif(!root||root.dataset.ready==='true')return;\nroot.dataset.ready='true';\nconst el=id=>document.getElementById(id),trace=el('trace'),legacyStatus=el('status'),legacyIds=el('ids');\nif(!trace||!legacyStatus||!legacyIds)return;\nconst actions={av18Connect:'connect',av18Seed:'seed',av18Execute:'execute',av18Retry:'retry',av18Readback:'readback',av18Reset:'reset'};\nconst named={'session':'Guest session','prepare_workflow':'Workflow persisted','prepare_document':'Source imported',\n 'plan':'Plan admitted by browser','search':'D1 source retrieved','workflow.run':'Saved workflow executed',\n 'artifact.save':'Evidence document saved','verify':'Server readback verified','error':'Review network / input'};\nconst stageNames=['search','run','artifact','verify'];\nconst short=value=>{\n const s=typeof value==='string'?value:'';\n return s.length>21?s.slice(0,8)+'…'+s.slice(-8):s||'—';\n};\nconst isHash=value=>typeof value==='string'&&/^[a-f0-9]{64}$/i.test(value);\nconst isId=value=>typeof value==='string'&&/^[0-9a-f-]{24,60}$/i.test(value);\nconst parse=()=>{try{\n const found=JSON.parse(trace.textContent);\n return Array.isArray(found)?found.slice(-25).filter(x=>x&&typeof x.step==='string'&&typeof x.kind==='string'&&!Array.isArray(x)):[];\n}catch{return[]}};\nconst stageOf=event=>{\n const e=event.evidence??{};\n if(event.step==='search'&&event.kind==='server'&&isId(e.documentId)&&isHash(e.passageSha256))return 'search';\n if(event.step==='workflow.run'&&event.kind==='server'&&isId(e.runId)&&isHash(e.resultSha256))return 'run';\n if(event.step==='artifact.save'&&event.kind==='server'&&isId(e.artifactId)&&isId(e.sourceRunId))return 'artifact';\n if(event.step==='verify'&&event.kind==='server_readback'&&e.verified===true\n  &&isId(e.runId)&&isId(e.artifactId)&&e.sourceRunId===e.runId&&isHash(e.contentSha256))return 'verify';\n return null;\n};\nconst nodes=Object.fromEntries([...root.querySelectorAll('[data-av18-stage]')].map(n=>[n.dataset.av18Stage,n]));\nlet receipt=null,armed=false,pending=false;\nfunction disarm(){\n armed=false;const b=el('av18Reset');b.dataset.armed='false';b.textContent='Delete guest workspace';\n}\nfunction observed(events){\n const steps=new Set(),completed=[];\n for(const event of events){const stage=stageOf(event);if(stage){steps.add(stage);completed.push({stage,event})}}\n const lastError=events.findLastIndex(e=>e.step==='error');\n const lastVerify=events.findLastIndex(e=>stageOf(e)==='verify');\n const verified=lastVerify>=0&&lastVerify>lastError;\n const v=verified?events[lastVerify].evidence:null;\n // Do not treat a readback as proof of the entire agent orchestration.\n const latest=key=>[...events].reverse().find(e=>stageOf(e)===key)?.evidence??null;\n const run=latest('run'),artifact=latest('artifact'),source=latest('search');\n if(v&&(run?.runId&&run.runId!==v.runId||artifact?.artifactId&&artifact.artifactId!==v.artifactId)){\n   return {steps,verified:false,v:null,run,artifact,source,problem:true};\n }\n return {steps,verified,v,run,artifact,source,problem: lastError>lastVerify};\n}\nfunction updateEvidence(data,events){\n const {steps,verified,v,run,artifact,source,problem}=data;\n stageNames.forEach(stage=>nodes[stage].dataset.state=steps.has(stage)?'observed':'idle');\n const count=steps.size;\n el('av18ProgressFill').style.width=String(count/4*100)+'%';\n el('av18ProgressLabel').textContent=count+' / 4 OBSERVED';\n const state=el('av18LiveState'),verdict=el('av18Verdict');\n state.dataset.state=verified?'verified':problem?'review':events.length?'observing':'idle';\n state.textContent=verified?'READBACK VERIFIED':problem?'NEEDS REVIEW':events.length?'OBSERVING API':'NOT EXECUTED';\n verdict.dataset.state=verified?'verified':problem?'review':'pending';\n el('av18VerdictText').textContent=verified?'Verified D1 readback':problem?'Verification requires review':'Awaiting observed proof';\n el('av18RunId').textContent=short(v?.runId||run?.runId);\n el('av18ArtifactId').textContent=short(v?.artifactId||artifact?.artifactId);\n el('av18Hash').textContent=verified?short(v.contentSha256):'NOT VERIFIED';\n el('av18Source').textContent=short(source?.passageSha256);\n receipt=verified?{\n  schema:'daniel-agent-bounded-guest-proof-v1',\n  scope:'browser-observed-server-readback',\n  atomicAgentReceipt:false,\n  verifiedReadback:true,\n  runId:v.runId,\n  artifactId:v.artifactId,\n  sourceRunId:v.sourceRunId,\n  contentSha256:v.contentSha256,\n  documentRevision:v.documentRevision??null,\n  citedPassageSha256:source?.passageSha256??null,\n  observedStageCount:count,\n  warning:'This is client-exported evidence of an individual persisted guest readback; not a signed server orchestration receipt.'\n }:null;\n el('av18Export').disabled=!receipt;\n if(!receipt)el('av18ExportStatus').textContent=problem?'An unresolved step prevents a verified receipt. Retry the same intent or re-read persisted data.':'Download becomes available after an actual SHA-256 server readback.';\n}\nfunction updateEvents(events){\n const list=el('av18EventList');list.replaceChildren();\n el('av18EventCount').textContent=String(events.length).padStart(2,'0');\n if(!events.length){\n  const li=document.createElement('li');li.className='av18-empty';\n  li.textContent='No tool evidence in this tab yet. Connect and prepare to begin.';\n  list.append(li);return\n }\n for(const [i,event] of events.slice(-7).entries()){\n  const li=document.createElement('li'),idx=document.createElement('span'),label=document.createElement('strong'),badge=document.createElement('em');\n  idx.className='av18-event-index';idx.textContent=String(events.length-Math.min(events.length,7)+i+1).padStart(2,'0');\n  label.textContent=Object.hasOwn(named,event.step)?named[event.step]:'Observed tool event';\n  badge.textContent=stageOf(event)?'API PROOF':event.step==='error'?'REVIEW':event.kind==='server_saved'?'D1 SAVED':'OBSERVED';\n  li.append(idx,label,badge);list.append(li);\n }\n}\nfunction syncControls(){\n for(const [id,origin] of Object.entries(actions)){\n  const local=el(id),target=el(origin);\n  if(!local||!target)continue;\n  const disabled=target.disabled===true;\n  if(local.disabled!==disabled)local.disabled=disabled;\n }\n const source=legacyIds.textContent,workspace=/Workspace:\\s*([^\\s]+)/.exec(source)?.[1];\n const hasWorkspace=workspace&&workspace!=='none';\n el('av18Session').textContent=hasWorkspace?'GUEST '+short(workspace):'NOT CONNECTED';\n const statusText=legacyStatus.textContent?.trim()||'Ready to inspect API responses.';\n if(!armed)el('av18OperatorStatus').textContent=statusText.slice(0,240);\n}\nfunction render(){\n const events=parse();updateEvidence(observed(events),events);updateEvents(events);syncControls();\n}\nlet queued=false;\nfunction queue(){\n if(queued)return;queued=true;queueMicrotask(()=>{queued=false;render()})\n}\nconst targetIds=['trace','status','ids','proof'];\nfor(const id of targetIds)new MutationObserver(queue).observe(el(id),{childList:true,characterData:true,subtree:true});\nfor(const old of Object.values(actions))new MutationObserver(queue).observe(el(old),{attributes:true,attributeFilter:['disabled']});\nconst oldQuery=el('query'),newQuery=el('av18Question');\nnewQuery.value=oldQuery.value;\nnewQuery.addEventListener('input',()=>{\n oldQuery.value=newQuery.value.slice(0,160);\n if(armed)disarm();\n});\nfor(const [id,target] of Object.entries(actions)){\n if(id==='av18Reset')continue;\n el(id).addEventListener('click',()=>{\n  if(armed)disarm();\n  if(id==='av18Execute'&&newQuery.value.trim()===''){\n   el('av18OperatorStatus').textContent='Enter a short, non-confidential source query first.';return;\n  }\n  if(id==='av18Execute')oldQuery.value=newQuery.value.slice(0,160);\n  el(target).click();queue();\n });\n}\nconst oldReset=el('reset'),resetButton=el('av18Reset');\nresetButton.addEventListener('click',()=>{\n if(oldReset.disabled||pending)return;\n if(!armed){\n  armed=true;resetButton.dataset.armed='true';\n  resetButton.textContent='Confirm deleting guest data';\n  el('av18OperatorStatus').textContent='Click again to delete this temporary D1 guest workspace, or press Escape to cancel.';\n  return;\n }\n disarm();pending=true;\n window.__AGENT_V18_RESET_CONFIRMED__=true;\n oldReset.click();\n queueMicrotask(()=>{pending=false;window.__AGENT_V18_RESET_CONFIRMED__=false;queue()});\n});\noldReset.addEventListener('click',()=>{\n if(window.__AGENT_V18_RESET_CONFIRMED__!==true){\n  resetButton.focus();\n  el('av18OperatorStatus').textContent='For a nonmodal reset, confirm twice using Delete guest workspace in Mission control.';\n }\n},true);\ndocument.addEventListener('keydown',e=>{\n if(e.key==='Escape'&&armed){disarm();el('av18OperatorStatus').textContent='Reset canceled. Guest data remains unchanged.'}\n},true);\ndocument.addEventListener('click',e=>{\n if(armed&&!resetButton.contains(e.target)){\n  disarm();el('av18OperatorStatus').textContent='Reset canceled. Guest data remains unchanged.';\n }\n},true);\nel('av18Export').addEventListener('click',()=>{\n if(!receipt)return;\n try{\n  const body=JSON.stringify(receipt,null,2);\n  const url=URL.createObjectURL(new Blob([body],{type:'application/json'}));\n  const a=document.createElement('a');a.href=url;a.download='daniel-agent-verified-guest-readback.json';\n  document.body.append(a);a.click();a.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),1500);\n  el('av18ExportStatus').textContent='Exported bounded guest readback. No source query, cookies, or user-authored document text included.';\n }catch{el('av18ExportStatus').textContent='Download unavailable; observed readback remains on screen.'}\n});\nrender();\n})();\n";
const AGENT_V18_CLIENT_CORE=CLIENT.replace("if(!confirm('Delete all data in this temporary guest workspace? This cannot be undone.'))return;","if(window.__AGENT_V18_RESET_CONFIRMED__!==true){status('Use the Agent cockpit to confirm deletion inline.');return;}window.__AGENT_V18_RESET_CONFIRMED__=false;");
const AGENT_V18_SECTION_ANCHOR='<section class="agent-visual-board"';
const AGENT_V18_END_ANCHOR='</div></main>';
const AGENT_V18_LEGACY_SCRIPT='<script src="/apps/agent/inspector.js" defer></script>';
function agentV18Html(){
 let h=agentV7Html();
 if(h.split(AGENT_V18_SECTION_ANCHOR).length!==2||h.split(AGENT_V18_END_ANCHOR).length!==2||h.split(AGENT_V18_LEGACY_SCRIPT).length!==2)throw Error('AGENT_V18_BASE_DOM_CHANGED');
 h=h.replace('<body>','<body class="agent-v18-body">').replace('Watch a bounded agent execute real tools.','Agent systems with inspectable receipts.');
 h=h.replace('</head>',AGENT_V18_CSS+'</head>');
 h=h.replace(AGENT_V18_SECTION_ANCHOR,AGENT_V18_HTML+'<details id="agentV18Advanced"><summary>Advanced API plan and raw evidence <small>ORIGINAL OBSERVABLE TOOLS ↗</small></summary>'+AGENT_V18_SECTION_ANCHOR);
 h=h.replace(AGENT_V18_END_ANCHOR,'</div></details></main>');
 h=h.replace(AGENT_V18_LEGACY_SCRIPT,AGENT_V18_LEGACY_SCRIPT+'<script src="/apps/agent/cockpit.js" defer></script>');
 return h;
}
