const JD_POPUP_V9_TAG="<script src=\"/ui-20261011/chat-widget-v9.js\" defer></script>";
const HEADERS={'x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'strict-origin-when-cross-origin','content-security-policy':"default-src 'none'; script-src 'self'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; object-src 'none'; form-action 'none'; base-uri 'none'; frame-ancestors 'none'"};
const response=(body,type,cache='no-store')=>new Response(body,{status:200,headers:{...HEADERS,'content-type':type,'cache-control':cache}});
export default {async fetch(req){const u=new URL(req.url);if(req.method!=='GET')return new Response('Method not allowed',{status:405,headers:{...HEADERS,allow:'GET'}});if(u.pathname==='/apps/agent/'||u.pathname==='/apps/agent')return response(agentV18Html().replace('</body>',JD_POPUP_V9_TAG+'</body>'),'text/html; charset=utf-8');if(u.pathname==='/apps/agent/client.js')return response(AGENT_V18_CLIENT_CORE,'application/javascript; charset=utf-8','public,max-age=120');if(u.pathname==='/apps/agent/cockpit.js')return response(AGENT_V18_CLIENT,'application/javascript; charset=utf-8','public,max-age=120');if(u.pathname==='/apps/agent/inspector.js')return response(AGENT_V7_CLIENT,'application/javascript; charset=utf-8','public,max-age=120');if(u.pathname==='/apps/agent/health')return response(JSON.stringify({ok:true,service:'daniel-deterministic-agent',mode:'bounded-http-orchestrator',ownDatabaseBinding:false,sharedGuestApi:true,atomicAgentReceipt:false}),'application/json; charset=utf-8');return new Response('Not found',{status:404,headers:HEADERS});}};
